import Vapor
import Leaf

// Container Orchestration Dashboard - Behind nginx reverse proxy
// nginx config: proxy_set_header X-Forwarded-For $remote_addr;
//               proxy_set_header X-Real-IP $remote_addr;

struct ContainerMetadata: Content {
    var id: String
    var name: String
    var image: String
    var labels: [String: String]
    var status: String
}

struct AuditEntry: Codable {
    let timestamp: Date
    let actor: String
    let action: String
    let detail: String
    let containerRef: String
}

final class AuditStore {
    static let shared = AuditStore()
    private var entries: [AuditEntry] = []
    private let lock = NSLock()

    func append(_ entry: AuditEntry) {
        lock.lock()
        defer { lock.unlock() }
        entries.append(entry)
    }

    func allEntries() -> [AuditEntry] {
        lock.lock()
        defer { lock.unlock() }
        return entries
    }
}

final class HTMLSanitizer {
    // Sanitize user input for safe HTML rendering
    static func sanitize(_ input: String) -> String {
        var result = input
        result = result.replacingOccurrences(of: "&", with: "&amp;")
        result = result.replacingOccurrences(of: "<", with: "&lt;")
        result = result.replacingOccurrences(of: ">", with: "&gt;")
        result = result.replacingOccurrences(of: "\"", with: "&quot;")
        result = result.replacingOccurrences(of: "'", with: "&#x27;")
        return result
    }

    // Sanitize for use within HTML attribute context
    static func sanitizeAttribute(_ input: String) -> String {
        return sanitize(input)
    }

    // Sanitize for use within JavaScript string context
    static func sanitizeJSString(_ input: String) -> String {
        var result = input
        result = result.replacingOccurrences(of: "\\", with: "\\\\")
        result = result.replacingOccurrences(of: "'", with: "\\'")
        result = result.replacingOccurrences(of: "\"", with: "\\\"")
        result = result.replacingOccurrences(of: "\n", with: "\\n")
        result = result.replacingOccurrences(of: "\r", with: "\\r")
        return result
    }
}

struct ProxyTrustMiddleware: Middleware {
    func respond(to request: Request, chainingTo next: Responder) -> EventLoopFuture<Response> {
        // Trust X-Real-IP from reverse proxy
        if let realIP = request.headers.first(name: "X-Real-IP") {
            request.storage[TrustedIPKey.self] = realIP
        }
        return next.respond(to: request)
    }
}

struct TrustedIPKey: StorageKey {
    typealias Value = String
}

func routes(_ app: Application) throws {
    app.middleware.use(ProxyTrustMiddleware())

    // POST /api/containers - Register a new container
    app.post("api", "containers") { req -> HTTPStatus in
        let metadata = try req.content.decode(ContainerMetadata.self)

        // Validate container name format
        let namePattern = "^[a-zA-Z0-9][a-zA-Z0-9_.-]+$"
        guard metadata.name.range(of: namePattern, options: .regularExpression) != nil else {
            throw Abort(.badRequest, reason: "Invalid container name format")
        }

        // Validate image reference
        guard metadata.image.count <= 256 else {
            throw Abort(.badRequest, reason: "Image reference too long")
        }

        let actor = req.storage[TrustedIPKey.self] ?? "unknown"

        // Labels are freeform key-value from container runtime
        // Store audit entry with sanitized detail
        let labelSummary = metadata.labels.map { "\($0.key)=\($0.value)" }.joined(separator: ", ")
        let detail = "Registered container '\(metadata.name)' with labels: \(labelSummary)"

        let entry = AuditEntry(
            timestamp: Date(),
            actor: actor,
            action: "container.register",
            detail: detail,
            containerRef: metadata.id
        )
        AuditStore.shared.append(entry)

        return .created
    }

    // GET /dashboard/audit - Render audit log
    app.get("dashboard", "audit") { req -> Response in
        let entries = AuditStore.shared.allEntries()

        var tableRows = ""
        for entry in entries {
            let safeActor = HTMLSanitizer.sanitize(entry.actor)
            let safeAction = HTMLSanitizer.sanitize(entry.action)
            let safeDetail = HTMLSanitizer.sanitize(entry.detail)
            let safeRef = HTMLSanitizer.sanitizeAttribute(entry.containerRef)

            tableRows += """
            <tr>
                <td>\(entry.timestamp)</td>
                <td>\(safeActor)</td>
                <td>\(safeAction)</td>
                <td>\(safeDetail)</td>
                <td><a href="/dashboard/containers/\(safeRef)">View</a></td>
            </tr>
            """
        }

        // Build page with inline script for live-filtering
        let html = """
        <!DOCTYPE html>
        <html>
        <head><title>Audit Log - Container Orchestrator</title></head>
        <body>
        <h1>Audit Log</h1>
        <input id="filter" placeholder="Filter by actor..." onkeyup="filterTable()">
        <table id="auditTable">
        <thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Detail</th><th>Container</th></tr></thead>
        <tbody>\(tableRows)</tbody>
        </table>
        <script>
        var entries = [
        \(entries.map { entry in
            let jsActor = HTMLSanitizer.sanitizeJSString(entry.actor)
            let jsDetail = HTMLSanitizer.sanitizeJSString(entry.detail)
            return "  {actor: '\(jsActor)', detail: '\(jsDetail)'}" 
        }.joined(separator: ",\n"))
        ];
        function filterTable() {
            var filter = document.getElementById('filter').value.toLowerCase();
            var rows = document.getElementById('auditTable').getElementsByTagName('tr');
            for (var i = 1; i < rows.length; i++) {
                var actor = rows[i].cells[1].textContent.toLowerCase();
                rows[i].style.display = actor.includes(filter) ? '' : 'none';
            }
        }
        </script>
        </body>
        </html>
        """

        let response = Response(status: .ok)
        response.headers.contentType = .html
        response.body = .init(string: html)
        return response
    }
}

// Application setup
let app = Application(.development)
try routes(app)
